/**
 * Centralized event constants for Alpine.js components
 *
 * This file defines all custom events used throughout the application
 * for component communication. Events are organized by component/module
 * for better maintainability and discoverability.
 */

export const events = {
  header: {
    mobileMenuOpened: 'header:mobile-menu-opened',
    mobileMenuClosed: 'header:mobile-menu-closed',
    closeAll: 'header:close-all',
  },

  search: {
    toggle: 'search:toggle',
    opened: 'search:opened',
    closed: 'search:closed',
  },

  megamenu: {
    opened: 'megamenu:opened',
    closed: 'megamenu:closed',
  },

  cart: {
    updated: 'cart:updated',
  },
  bodyOverflow: {
    lock: 'body-overflow:lock',
    unlock: 'body-overflow:unlock',
  },

  // Product image gallery events
  gallery: {
    zoomOpened: 'gallery:zoom-opened',
    zoomClosed: 'gallery:zoom-closed',
    slideChanged: 'gallery:slide-changed',
    zoomChanged: 'gallery:zoom-changed',
  },

  sizeGuide: {
    open: 'size-guide:open',
    close: 'size-guide:close',
  },
  // Shopify theme editor events
  shopify: {
    blockSelect: 'shopify:block:select',
    blockDeselect: 'shopify:block:deselect',
  },
};

/**
 * Helper function to dispatch events with consistent naming
 * @param {Object} context - Alpine.js component context (this)
 * @param {string} eventName - Event name from the events object
 * @param {any} detail - Event detail payload
 */
export function dispatchEvent(context, eventName, detail = null) {
  if (detail) {
    context.$dispatch(eventName, detail);
  } else {
    context.$dispatch(eventName);
  }
}

/**
 * Helper function to create event listener directive for Alpine.js
 * @param {string} eventName - Event name from the events object
 * @param {Function} handler - Event handler function
 * @param {string} modifier - Optional modifier (e.g., 'window', 'document')
 * @returns {string} - Alpine.js event directive
 */
export function createEventDirective(eventName, modifier = '') {
  const suffix = modifier ? `.${modifier}` : '';
  return `@${eventName}${suffix}`;
}
